/*
 * config_frames_test -- the whole machine held to MAME with no MAME: the baked CONFIG
 * client boots on the FujiNet cartridge, link down, and its frames must hash as MAME's
 * did for the same set-up (config_golden.h, generated by tools/ab/config_golden.py), frame
 * for frame from frame 0, on the NTSC machine and the PAL one. CONFIG draws and polls the
 * whole console -- the F8's ROMC cycles and the clocks, the ports and the VRAM strobe, the
 * palette columns, the picture's geometry, and the cartridge's flat-image serving and
 * mailbox -- so a match covers all of it at once.
 *
 * Two BIOSes, two sets of goldens. With the app's own stand-in (core/chf/stub.c, the one
 * with no ROM, which is what the CI has) the goldens are MAME running the same stand-in
 * under the real BIOS's file names; with the console's real BIOS (CHF_BIOS_DIR holds
 * sl31253.rom and sl31254.rom) they are MAME with its own. A half whose goldens are not
 * there yet, or whose BIOS is not, is skipped; the test is skipped (77) if both are.
 *
 * Copyright (C) 2026 Thomas Cherryhomes
 * SPDX-License-Identifier: GPL-3.0-or-later
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "chf_internal.h"
#include "config_golden.h"

static unsigned long long fnv64(const uint32_t *px, size_t n)
{
    unsigned long long h = 14695981039346656037ull;

    for (size_t i = 0; i < n; i++) {
        h ^= px[i] & 0xffffffu;
        h *= 1099511628211ull;
    }
    return h;
}

static int read_rom(const char *dir, const char *name, uint8_t *dst, size_t n)
{
    char path[1024];
    FILE *f;
    size_t got;

    snprintf(path, sizeof path, "%s/%s", dir, name);
    f = fopen(path, "rb");
    if (!f)
        return -1;
    got = fread(dst, 1, n, f);
    fclose(f);
    return got == n ? 0 : -1;
}

/* one run: `machine` on a BIOS (real halves, or NULL for the stand-in), CONFIG on the cartridge */
static int run(const char *label, int machine, const uint8_t *lo, const uint8_t *hi, const config_golden_t *g, int n)
{
    static chf_machine_t m;
    chf_machine_opts_t mo;
    chf_fujinet_t *fj = chf_fujinet_create();
    char why[160];
    int failures = 0, next = 0, last = 0;

    for (int i = 0; i < n; i++)
        if (g[i].frame > last)
            last = g[i].frame;
    if (!fj || chf_fujinet_power_on(fj, NULL, 0, "", true, why, sizeof why) != 0) {
        fprintf(stderr, "config_frames: cannot power on the cartridge: %s\n", why);
        return 1;
    }
    memset(&mo, 0, sizeof mo);
    mo.machine = machine;
    mo.bios_lo = lo;
    mo.bios_hi = hi;
    mo.bios_id = lo ? CHF_ROM_SL31253 : -1;
    mo.cart = chf_fujinet_cart(fj);
    mo.fujinet = fj;
    chf_machine_init(&m, &mo);
    chf_machine_check_cart(&m);

    for (int f = 0; f <= last; f++) {
        chf_machine_run_frame(&m);
        while (next < n && g[next].frame == f) {
            const unsigned long long h = fnv64(m.fb, CHF_FB_WIDTH * CHF_FB_HEIGHT);

            if (h != g[next].hash) {
                if (failures < 6)
                    printf("FAIL: %s frame %d is %016llx, MAME's is %016llx\n", label, f, h, g[next].hash);
                failures++;
            }
            next++;
        }
    }
    printf("%s: %s: %d of %d frames match MAME (CONFIG's picture, frames 0-%d)\n", failures ? "FAIL" : "ok", label, n - failures,
           n, last);
    if (m.parked)
        printf("  (the machine parked: %s)\n", m.park_why);
    chf_fujinet_destroy(fj);
    return failures;
}

int main(void)
{
    static uint8_t lo[CF_BIOS_HALF], hi[CF_BIOS_HALF];
    const char *dir = getenv("CHF_BIOS_DIR");
    int failures = 0, ran = 0;

    /* the app's stand-in */
    if (k_config_stub_ntsc_n > 0 && chf_stub_rom[0] != 0xff) {
        failures += run("stand-in BIOS, NTSC", CHF_MACHINE_CHANNELF, NULL, NULL, k_config_stub_ntsc, k_config_stub_ntsc_n);
        failures += run("stand-in BIOS, PAL", CHF_MACHINE_VIDEOPLAY, NULL, NULL, k_config_stub_pal, k_config_stub_pal_n);
        ran++;
    } else {
        printf("note: no stand-in goldens yet (tools/ab/config_golden.py --stub-rompath)\n");
    }
    /* the console's own BIOS, when the user's copy is at hand */
    if (dir && *dir && read_rom(dir, "sl31253.rom", lo, sizeof lo) == 0 && read_rom(dir, "sl31254.rom", hi, sizeof hi) == 0) {
        failures += run("real BIOS (sl31253), NTSC", CHF_MACHINE_CHANNELF, lo, hi, k_config_real_ntsc, k_config_real_ntsc_n);
        failures += run("real BIOS (sl31253), PAL", CHF_MACHINE_VIDEOPLAY, lo, hi, k_config_real_pal, k_config_real_pal_n);
        ran++;
    } else {
        printf("note: no real BIOS (CHF_BIOS_DIR)\n");
    }
    if (!ran) {
        printf("SKIP: neither the stand-in's goldens nor a real BIOS are available\n");
        return 77;
    }
    printf("%d failure(s)\n", failures);
    return failures ? 1 : 0;
}
